using System;
using System.Collections.Generic;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Text;

namespace FancyZonesStandalone
{
    /// <summary>Export / import FancyZones layouts and settings as a single .zip.</summary>
    internal static class Backup
    {
        // Portable files only. editor-parameters.json and app-zone-history.json describe this
        // machine's current monitors/windows and are regenerated by FancyZones.
        public static readonly string[] Files =
        {
            "settings.json",
            "custom-layouts.json",
            "applied-layouts.json",
            "default-layouts.json",
            "layout-hotkeys.json",
            "layout-templates.json",
        };

        private const string MetaName = "fancyzones-standalone-export.json";

        public static int Export(string zipPath)
        {
            var tmp = zipPath + ".tmp";
            if (File.Exists(tmp)) File.Delete(tmp);
            int count = 0;
            using (var zip = ZipFile.Open(tmp, ZipArchiveMode.Create))
            {
                foreach (var name in Files)
                {
                    var src = Path.Combine(Paths.FzData, name);
                    if (!File.Exists(src)) continue;
                    zip.CreateEntryFromFile(src, name, CompressionLevel.Optimal);
                    count++;
                }
                var v = PackageVersion.Load();
                var meta = zip.CreateEntry(MetaName);
                using (var w = new StreamWriter(meta.Open(), new UTF8Encoding(false)))
                    w.Write("{\"exported\":\"" + DateTime.UtcNow.ToString("o") + "\",\"machine\":\"" +
                            Environment.MachineName.Replace("\"", "") + "\",\"package\":\"" + v.Tag + "\"}");
            }
            if (count == 0) { File.Delete(tmp); throw new InvalidOperationException("No FancyZones layouts or settings found to export yet."); }
            if (File.Exists(zipPath)) File.Delete(zipPath);
            File.Move(tmp, zipPath);
            return count;
        }

        /// <summary>Names of importable files inside a backup zip (validates it first).</summary>
        public static List<string> Inspect(string zipPath)
        {
            using (var zip = ZipFile.OpenRead(zipPath))
            {
                var found = zip.Entries.Select(e => e.Name)
                    .Where(n => Files.Contains(n, StringComparer.OrdinalIgnoreCase)).ToList();
                if (found.Count == 0) throw new InvalidDataException("This zip doesn't contain any FancyZones layout or settings files.");
                foreach (var e in zip.Entries.Where(e => Files.Contains(e.Name, StringComparer.OrdinalIgnoreCase)))
                {
                    using (var r = new StreamReader(e.Open()))
                    {
                        var text = r.ReadToEnd().TrimStart('﻿', ' ', '\r', '\n', '\t');
                        if (!text.StartsWith("{") && !text.StartsWith("["))
                            throw new InvalidDataException(e.Name + " is not valid JSON.");
                    }
                }
                return found;
            }
        }

        /// <summary>Imports a backup. Current files are saved to a pre-import backup first. Returns that backup's path.</summary>
        public static string Import(string zipPath)
        {
            Inspect(zipPath);
            Directory.CreateDirectory(Paths.BackupDir);
            var safety = Path.Combine(Paths.BackupDir, "pre-import-" + DateTime.Now.ToString("yyyyMMdd-HHmmss") + ".zip");
            try { Export(safety); } catch (InvalidOperationException) { safety = null; } // nothing to back up

            using (var zip = ZipFile.OpenRead(zipPath))
            {
                foreach (var e in zip.Entries)
                {
                    // Flatten and allow-list names: no paths from the archive are ever used.
                    var name = Files.FirstOrDefault(f => f.Equals(e.Name, StringComparison.OrdinalIgnoreCase));
                    if (name == null) continue;
                    var dest = Path.Combine(Paths.FzData, name);
                    var tmp = dest + ".importing";
                    e.ExtractToFile(tmp, true);
                    if (File.Exists(dest)) File.Delete(dest);
                    File.Move(tmp, dest);
                }
            }
            return safety;
        }
    }
}
